#!/usr/bin/env bash
# Flag AI-tool attribution in commit messages and PR descriptions (AGENTS.md rule 7).
#
# Usage:
#   check-attribution.sh [FILE|-]...   scan files (no argument or "-" reads stdin)
#   check-attribution.sh --self-test   run built-in positive/negative cases
#
# Flagged:
#   - "Co-Authored-By:" trailer lines (case-insensitive, any value)
#   - "Generated with|by" followed by an AI tool name (Claude, Kiro, Copilot, ChatGPT, Cursor)
#   - the robot emoji
#   - claude.ai/code links and kiro.dev links whose path contains "session"
# Ordinary mentions (CLAUDE.md, .claude/, kiro-cli, "Claude Code" in prose) are not flagged.
#
# Exit codes: 0 clean, 1 attribution found, 2 usage or I/O error.
# Portable: bash 3.2 (macOS), Linux, Git Bash. No GNU-only grep options.

set -u

ROBOT_EMOJI=$(printf '\360\237\244\226')
TOOLS='(github[[:space:]]+)?(claude|kiro|copilot|chatgpt|cursor)'
# What may follow the tool name: whitespace, closing/inline punctuation, a sentence-ending dot, or end of line.
END='([[:space:]]|[],;:)!?*_-]|\.([[:space:]]|$)|$)'

RE_TRAILER='^[[:space:]>*-]*co-authored-by[[:space:]]*:'
RE_GENERATED="generated[[:space:]]+(with|by)[[:space:]]+[^[:alnum:]]*${TOOLS}${END}"
RE_CLAUDE_URL='claude\.ai/code([^[:alnum:]_]|$)'
RE_KIRO_URL='kiro\.dev/[^[:space:])>]*session'

FOUND=0

# rule FILE LABEL REASON GREP_FLAGS PATTERN
# Prints "LABEL:LINE: [REASON] TEXT" per match and sets FOUND=1. Returns 2 on I/O error.
rule() {
  local file=$1 label=$2 reason=$3 flags=$4 pattern=$5 out rc
  # shellcheck disable=SC2086 # flags are intentionally word-split
  out=$(LC_ALL=C grep -n $flags -e "$pattern" -- "$file" 2>/dev/null)
  rc=$?
  case $rc in
    0)
      FOUND=1
      printf '%s\n' "$out" | while IFS= read -r line; do
        printf '%s:%s: [%s] %s\n' "$label" "${line%%:*}" "$reason" "${line#*:}"
      done
      ;;
    1) ;;
    *)
      printf 'check-attribution: cannot read %s\n' "$file" >&2
      return 2
      ;;
  esac
  return 0
}

# scan FILE LABEL -> sets FOUND, returns 2 on I/O error
scan() {
  local file=$1 label=$2 rc=0
  rule "$file" "$label" 'Co-Authored-By trailer' '-E -i' "$RE_TRAILER" || rc=2
  rule "$file" "$label" 'generated by an AI tool' '-E -i' "$RE_GENERATED" || rc=2
  rule "$file" "$label" 'robot emoji' '-F' "$ROBOT_EMOJI" || rc=2
  rule "$file" "$label" 'Claude session link' '-E -i' "$RE_CLAUDE_URL" || rc=2
  rule "$file" "$label" 'Kiro session link' '-E -i' "$RE_KIRO_URL" || rc=2
  return $rc
}

make_temp() {
  mktemp "${TMPDIR:-/tmp}/check-attribution.XXXXXX"
}

self_test() {
  local tmp failures=0 total=0
  tmp=$(make_temp) || { echo 'check-attribution: mktemp failed' >&2; return 2; }
  # Expand $tmp now: the variable is local and gone when the EXIT trap fires.
  trap "rm -f '$tmp'" EXIT

  # expect flag|ok TEXT
  expect() {
    local want=$1 text=$2 got
    total=$((total + 1))
    printf '%s\n' "$text" >"$tmp"
    FOUND=0
    scan "$tmp" self-test >/dev/null 2>&1
    if [ "$FOUND" -eq 1 ]; then got=flag; else got=ok; fi
    if [ "$got" != "$want" ]; then
      failures=$((failures + 1))
      printf 'FAIL: expected %s, got %s: %s\n' "$want" "$got" "$text" >&2
    fi
  }

  # Must be flagged
  expect flag 'Co-Authored-By: Claude <noreply@anthropic.com>'
  expect flag 'co-authored-by: Some Person <p@example.com>'
  expect flag 'CO-AUTHORED-BY:anything'
  expect flag '- Co-Authored-By: Kiro'
  expect flag 'Generated with Claude Code'
  expect flag "Generated with [Claude Code](https://example.com/x)"
  expect flag 'generated by ChatGPT'
  expect flag 'Generated by GitHub Copilot.'
  expect flag 'Generated with Cursor'
  expect flag 'Generated with Kiro'
  expect flag "Done ${ROBOT_EMOJI}"
  expect flag 'See https://claude.ai/code/session_01abc'
  expect flag 'Session: https://kiro.dev/sessions/abc123'

  # Must not be flagged
  expect ok 'Update CLAUDE.md with the new rules'
  expect ok 'Add .claude/settings.json to .gitignore'
  expect ok 'Run kiro-cli chat to explore the repo'
  expect ok 'We use Claude Code and Kiro for reviews'
  expect ok 'Generated by Terraform'
  expect ok 'Generated with terraform-docs'
  expect ok 'Generated by GitHub Actions'
  expect ok 'Generated by CLAUDE.md'
  expect ok 'Generated with Cursorless'
  expect ok 'Explain what a Co-Authored-By trailer is'
  expect ok 'Read https://kiro.dev/docs/steering'
  expect ok 'Read https://claude.ai/ for pricing'
  expect ok 'feat(ci): add PR governance checks'

  if [ "$failures" -ne 0 ]; then
    printf 'self-test: %d of %d cases failed\n' "$failures" "$total" >&2
    return 1
  fi
  printf 'self-test: %d cases passed\n' "$total"
  return 0
}

usage() {
  sed -n '2,17p' "$0" | sed 's/^# \{0,1\}//'
}

main() {
  local status=0 rc arg tmp

  case ${1:-} in
    --self-test) self_test; return $? ;;
    -h|--help) usage; return 0 ;;
  esac

  [ $# -gt 0 ] || set -- -

  for arg in "$@"; do
    FOUND=0
    rc=0
    if [ "$arg" = "-" ]; then
      tmp=$(make_temp) || { echo 'check-attribution: mktemp failed' >&2; return 2; }
      cat >"$tmp"
      scan "$tmp" '<stdin>' || rc=2
      rm -f "$tmp"
    elif [ -r "$arg" ] && [ -f "$arg" ]; then
      scan "$arg" "$arg" || rc=2
    else
      printf 'check-attribution: cannot read %s\n' "$arg" >&2
      rc=2
    fi
    if [ "$rc" -eq 2 ]; then
      status=2
    elif [ "$FOUND" -eq 1 ] && [ "$status" -eq 0 ]; then
      status=1
    fi
  done

  if [ "$status" -eq 1 ]; then
    printf 'check-attribution: remove the AI-tool attribution above (AGENTS.md rule 7).\n' >&2
  fi
  return "$status"
}

main "$@"
